// Lấy SQL query từ output
const sqlQuery = $input.first().json.output;

// Regex để tìm và extract thời gian trong format 'YYYY-MM-DD HH:MM:SS'
const timeRegex = /'(\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2})'/g;

// Function để chuyển UTC+7 về UTC (trừ 7 giờ)
function convertToUTC(timeString) {
  const date = new Date(timeString + '+07:00'); // Thêm timezone +07:00
  return date.toISOString().slice(0, 19).replace('T', ' '); // Format về YYYY-MM-DD HH:MM:SS
}

// Replace tất cả thời gian trong SQL query
const updatedQuery = sqlQuery.replace(timeRegex, (match, timeString) => {
  const utcTime = convertToUTC(timeString);
  return `'${utcTime}'`;
});

return {
  output: updatedQuery
};
